@register.simple_tag
def social_icon(platform, variant="filled", size=24):
    """Render an SVG icon for the given social platform."""
    data = ICONS.get(platform)
    if not data:
        return ""
    path = data.get(variant, list(data.values())[0])
    return (
        f'<svg xmlns="http://www.w3.org/2000/svg" width="{size}" height="{size}" '
        f'viewBox="0 0 24 24" fill="currentColor" class="ks-social-icon">'
        f"{path}</svg>"
    )
